def _generate_expression(self):
    # turn my _format attribute into the _expression attribute
    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # Validate that the part is fully enclosed in matching braces
            if not part.endswith('}'):
                raise ValueError(
                    "part %r is not fully enclosed in matching braces" % part)
            # this will be a braces-delimited field to handle
            e.append(self._handle_field(part))
        else:
            # Check for unmatched closing braces in literal text
            if part.endswith('}'):
                raise ValueError(
                    "part %r contains an unmatched closing brace" % part)
            # just some text to match
            e.append(REGEX_SAFETY.sub(self._regex_replace, part))
    return ''.join(e)
